import{_ as e,o as t,c as r,a2 as s}from"./chunks/framework.BvlN9b-o.js";const u=JSON.parse('{"title":"v1 能力覆盖与验收","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/v1-coverage.md","filePath":"architecture/v1-coverage.md"}'),o={name:"architecture/v1-coverage.md"};function d(b,a,l,n,i,c){return t(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="v1-能力覆盖与验收" tabindex="-1">v1 能力覆盖与验收 <a class="header-anchor" href="#v1-能力覆盖与验收" aria-label="Permalink to &quot;v1 能力覆盖与验收&quot;">​</a></h1><p>本页是 v1 的总账：规范 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/docs/saas-template-architecture-spec.md" target="_blank" rel="noreferrer">§8.6 特性覆盖矩阵</a>的每一行在这里落成真实链接——运行入口、源码导读、在线教程与验证一一对应，链接目标由文档构建的存在性检查守护（源文件不存在构建即失败），教程与源码不会悄悄失配。矩阵只收<strong>已交付</strong>的能力；设计说明（如规范 §15.2 的 Mobile、Outbox 扩展章）不进矩阵、不标覆盖，文档不留填空。Core 能力的证据直接写在矩阵里，并保证在《移除示例》之后仍然成立。</p><h2 id="四条阅读路径" tabindex="-1">四条阅读路径 <a class="header-anchor" href="#四条阅读路径" aria-label="Permalink to &quot;四条阅读路径&quot;">​</a></h2><ol><li><strong>快速开始</strong>：<a href="./../">快速开始</a>——工具链、<code>just dev</code>、注册首个账号、服务状态与失败场景。</li><li><strong>跟做教程</strong>：从<a href="./../tutorials/first-request">第一条全栈请求</a>起步逐章跟做，每章对应真实命令与测试。</li><li><strong>实现自己的业务</strong>：<a href="./../tutorials/example-removal">移除示例，接入自己的业务</a>——按所有权清单删掉知识库示例，Core 照常运行。</li><li><strong>验证与参考手册</strong>：<a href="./../testing/feedback-loop">运行测试与检查</a>、<a href="./boundaries">Core 与示例边界</a>与生成参考（<a href="./../reference/api">API 合同</a>、<a href="./../reference/config">API 配置</a>）。</li></ol><h2 id="core-能力矩阵" tabindex="-1">Core 能力矩阵 <a class="header-anchor" href="#core-能力矩阵" aria-label="Permalink to &quot;Core 能力矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模板能力</th><th>运行入口</th><th>源码导读</th><th>跟做</th><th>验证</th></tr></thead><tbody><tr><td>注册、Session、配置</td><td><code>/register</code>；<code>POST /api/v1/auth/register</code>、<code>/auth/session</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/crates/app/src/modules/identity" target="_blank" rel="noreferrer">identity</a>（含 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/crates/app/src/modules/identity/password_reset" target="_blank" rel="noreferrer">password_reset</a>）、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/crates/platform/src/config.rs" target="_blank" rel="noreferrer">config.rs</a></td><td><a href="./../tutorials/registration">02</a> · <a href="./../tutorials/sessions">03</a> · <a href="./../tutorials/password-reset">18</a></td><td>注册/会话/密码重置 API 测试、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/apps/api/tests/config.rs" target="_blank" rel="noreferrer">config</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/tests/e2e/registration.spec.ts" target="_blank" rel="noreferrer">e2e</a></td></tr><tr><td>Organization、RBAC</td><td><code>/members</code>；角色调整、停用撤销会话、最后 Owner 保护</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/crates/app/src/modules/organization" target="_blank" rel="noreferrer">organization</a></td><td><a href="./../tutorials/members">08</a></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/apps/api/tests/members.rs" target="_blank" rel="noreferrer">members</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/tests/e2e/members.spec.ts" target="_blank" rel="noreferrer">e2e</a></td></tr><tr><td>CRUD、SQLx、迁移</td><td><code>just migrate</code>；迁移集合与 checksum 必须匹配源码</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/migrations" target="_blank" rel="noreferrer">migrations/</a></td><td><a href="./../tutorials/first-request">01</a></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/apps/api/tests/migration.rs" target="_blank" rel="noreferrer">migration</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/tests/e2e/status.spec.ts" target="_blank" rel="noreferrer">e2e 迁移版本</a></td></tr><tr><td>OpenAPI、SDK、多端 Views</td><td><code>pnpm contracts:check</code>；Electron 打开同一页面</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/packages/contracts" target="_blank" rel="noreferrer">contracts</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/packages/sdk/src" target="_blank" rel="noreferrer">sdk</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/packages/views/src" target="_blank" rel="noreferrer">views</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/apps/desktop/src" target="_blank" rel="noreferrer">desktop</a></td><td><a href="./../tutorials/electron-shell">20</a></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/tests/desktop/shell.spec.ts" target="_blank" rel="noreferrer">壳冒烟</a>、IPC 合同测试</td></tr><tr><td>RustFS / S3 / 文件权限</td><td><code>bootstrap-storage</code> 初始化私有 bucket 与浏览器 CORS</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/crates/app/src/modules/files" target="_blank" rel="noreferrer">files</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/crates/platform/src/object_storage.rs" target="_blank" rel="noreferrer">object_storage.rs</a></td><td>—（门禁与栈启动覆盖）</td><td>每个测试栈启动时的 bucket 初始化检查</td></tr><tr><td>Job、Worker、幂等</td><td><code>just dev</code> 启动 Worker；失败任务可显式重试</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/crates/app/src/modules/jobs" target="_blank" rel="noreferrer">jobs</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/crates/app/src/modules/idempotency" target="_blank" rel="noreferrer">idempotency</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/apps/worker/src" target="_blank" rel="noreferrer">worker</a></td><td>—（门禁与测试覆盖）</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/apps/api/tests/jobs.rs" target="_blank" rel="noreferrer">jobs</a>（认领/心跳/重试）</td></tr><tr><td>Notification / Mail</td><td>注册与密码重置邮件到达 <a href="http://127.0.0.1:8025" target="_blank" rel="noreferrer">Mailpit</a></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/crates/app/src/modules/notifications" target="_blank" rel="noreferrer">notifications</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/crates/platform/src/mail.rs" target="_blank" rel="noreferrer">mail.rs</a></td><td><a href="./../tutorials/password-reset">18</a></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/tests/e2e/password-reset.spec.ts" target="_blank" rel="noreferrer">e2e</a>、邮件 key 工具测试</td></tr><tr><td>Audit / Tracing</td><td><code>/audit</code>；<code>GET /api/v1/audit-events</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/crates/app/src/modules/audit" target="_blank" rel="noreferrer">audit</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/crates/platform/src/telemetry" target="_blank" rel="noreferrer">telemetry</a></td><td>—（门禁与测试覆盖）</td><td>遥测测试（含中断演练）</td></tr><tr><td>Redis / Rate Limit</td><td><code>/system</code> 展示缓存与限流状态</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/crates/app/src/modules/rate_limit" target="_blank" rel="noreferrer">rate_limit</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/crates/app/src/modules/system/cache.rs" target="_blank" rel="noreferrer">system cache</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/crates/platform/src/cache.rs" target="_blank" rel="noreferrer">platform cache</a></td><td><a href="./../tutorials/rate-limits">17</a></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/tests/e2e/rate-limits.spec.ts" target="_blank" rel="noreferrer">e2e</a>、限流支持测试</td></tr><tr><td>API Key</td><td><code>/api-keys</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/crates/app/src/modules/api_keys" target="_blank" rel="noreferrer">api_keys</a>（签发与会话验证）</td><td>—（门禁与测试覆盖）</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/apps/web/src/api-keys.test.tsx" target="_blank" rel="noreferrer">api-keys View 测试</a></td></tr><tr><td>测试 / 性能</td><td><code>just perf-ci</code>（门禁）；夜跑负载/饱和/轨迹报告</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/scripts/perf" target="_blank" rel="noreferrer">scripts/perf</a>（含 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/scripts/perf/baselines.json" target="_blank" rel="noreferrer">baselines.json</a>）</td><td>—（预算随 <code>just check</code> 执行）</td><td><code>just perf-ci</code>、预算/报告单元测试、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/.github/workflows/perf-nightly.yml" target="_blank" rel="noreferrer">perf-nightly.yml</a></td></tr><tr><td>部署 / 恢复</td><td><code>just production-up</code> / <code>production-backup</code> / <code>production-restore-drill</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/compose.production.yaml" target="_blank" rel="noreferrer">compose.production.yaml</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/deploy/production" target="_blank" rel="noreferrer">deploy/production</a>、production-*.mjs</td><td><a href="./../tutorials/single-machine-production">21</a> · <a href="./../tutorials/backup-restore">22</a></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/tests/tooling/production-compose.test.mjs" target="_blank" rel="noreferrer">production-compose</a>、备份清单/sigv4 工具测试</td></tr><tr><td>文档 / 可替换业务</td><td><code>just check-core</code>（删例后门禁）；<code>just docs</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/scripts/example-remove.mjs" target="_blank" rel="noreferrer">example-remove.mjs</a></td><td><a href="./../tutorials/example-removal">23</a></td><td>CI 每 PR 完整删例演练、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/tests/tooling/example-remove.test.mjs" target="_blank" rel="noreferrer">example-remove 工具测试</a></td></tr></tbody></table><h2 id="知识库示例演示的能力-随示例移除" tabindex="-1">知识库示例演示的能力（随示例移除） <a class="header-anchor" href="#知识库示例演示的能力-随示例移除" aria-label="Permalink to &quot;知识库示例演示的能力（随示例移除）&quot;">​</a></h2><p>本节由知识库示例演示，随《<a href="./../tutorials/example-removal">移除示例</a>》一起消失；删除示例后，上面的 Core 矩阵仍然成立，替换业务按同样的公开接口接入。</p><p>规范 §8.6 的「业务约束、并发」一行完全由示例演示：</p><table tabindex="0"><thead><tr><th>模板能力</th><th>运行入口</th><th>源码导读</th><th>跟做</th><th>验证</th></tr></thead><tbody><tr><td>业务约束、并发</td><td>编辑页保存触发 409；最后 Owner 保护</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/crates/app/src/modules/knowledge/domain.rs" target="_blank" rel="noreferrer">domain.rs</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/crates/app/src/modules/knowledge/deletion.rs" target="_blank" rel="noreferrer">deletion.rs</a></td><td><a href="./../tutorials/edit-conflicts">06</a> · <a href="./../tutorials/deletion-cleanup">12</a></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/apps/api/tests/deletion.rs" target="_blank" rel="noreferrer">deletion</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/tests/e2e/deletion.spec.ts" target="_blank" rel="noreferrer">e2e</a></td></tr></tbody></table><p>其余各行的示例演示：</p><ul><li><strong>资源授权</strong>：Reader/Editor 授予与撤销 → <a href="./../tutorials/library-grants">07</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/crates/app/src/modules/knowledge/grants.rs" target="_blank" rel="noreferrer">grants.rs</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/tests/e2e/knowledge-grants.spec.ts" target="_blank" rel="noreferrer">e2e</a></li><li><strong>知识文档 CRUD、搜索、预览与分页</strong> → <a href="./../tutorials/personal-documents">04</a> · <a href="./../tutorials/search-preview">05</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/apps/api/tests/knowledge.rs" target="_blank" rel="noreferrer">knowledge</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/tests/e2e/knowledge.spec.ts" target="_blank" rel="noreferrer">e2e</a></li><li><strong>附件上传/下载与 Markdown 引用</strong> → <a href="./../tutorials/attachments">09</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/crates/app/src/modules/knowledge/attachments.rs" target="_blank" rel="noreferrer">attachments.rs</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/tests/e2e/attachments.spec.ts" target="_blank" rel="noreferrer">e2e</a></li><li><strong>导出 ZIP 与任务恢复</strong> → <a href="./../tutorials/document-exports">10</a> · <a href="./../tutorials/job-recovery">11</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/apps/api/tests/exports.rs" target="_blank" rel="noreferrer">exports</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/tests/e2e/exports.spec.ts" target="_blank" rel="noreferrer">e2e</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/tests/e2e/job-recovery.spec.ts" target="_blank" rel="noreferrer">恢复 e2e</a></li><li><strong>导出通知与已读状态</strong> → <a href="./../tutorials/export-notifications">13</a></li><li><strong>知识操作的审计追溯</strong> → <a href="./../tutorials/audit-history">14</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/apps/api/tests/audit_knowledge.rs" target="_blank" rel="noreferrer">audit_knowledge</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/tests/e2e/audit.spec.ts" target="_blank" rel="noreferrer">e2e</a></li><li><strong>API Key 读取有权文档</strong> → <a href="./../tutorials/api-keys">15</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/apps/api/tests/key_documents.rs" target="_blank" rel="noreferrer">key_documents</a></li><li><strong>版本化正文缓存</strong> → <a href="./../tutorials/versioned-cache">16</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/apps/api/tests/cached_documents.rs" target="_blank" rel="noreferrer">cached_documents</a></li><li><strong>观测示例链路</strong> → <a href="./../tutorials/observability">19</a></li><li><strong>确定性预算、负载/饱和/轨迹与桌面渲染长测的教程</strong> → <a href="./../tutorials/perf-gates">24</a> · <a href="./../tutorials/load-reports">25</a> · <a href="./../tutorials/desktop-soak">26</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/apps/api/tests/perf_documents.rs" target="_blank" rel="noreferrer">perf_documents</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/tests/desktop/soak.spec.ts" target="_blank" rel="noreferrer">桌面 soak</a></li><li><strong>Electron 打开知识示例</strong> → <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/tests/desktop/knowledge-shell.spec.ts" target="_blank" rel="noreferrer">knowledge-shell</a></li><li><strong>示例所有权清单</strong> → <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/examples/knowledge-base/manifest.json" target="_blank" rel="noreferrer">examples/knowledge-base/manifest.json</a></li></ul><p>示例对应的验收补充：渲染进程资源长测由夜跑 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/scripts/perf/desktop-soak.mjs" target="_blank" rel="noreferrer">desktop-soak</a> 产出报告（artifact 保留 30 天）；教程 04–19、24–26 随示例逐票交付。</p><h2 id="验收汇总" tabindex="-1">验收汇总 <a class="header-anchor" href="#验收汇总" aria-label="Permalink to &quot;验收汇总&quot;">​</a></h2><ul><li><strong>默认全栈</strong>：教程从<a href="./../tutorials/first-request">第一条全栈请求</a>起步逐票交付；日常门禁 <code>just check</code>，真实浏览器旅程 <code>just e2e</code>，里程碑 <code>just check-full</code>。</li><li><strong>Electron</strong>：<a href="./../tutorials/electron-shell">安全壳教程</a> + 桌面冒烟（<code>just desktop-smoke</code>，CI 每 PR）。</li><li><strong>Mobile</strong>：未实现，也不在 v1 计划内（实施票 <a href="https://github.com/CaiZongyuan/axum-saas-template/issues/22" target="_blank" rel="noreferrer">#22</a> 记录为 not planned）。规范 §15.2 与测试策略中的 Mobile 条目保留为设计说明、不据此实施（实施决定以 #22 为准，该差异有意保留）；无对应检查、无文档填空。</li><li><strong>性能</strong>：确定性预算随 <code>just check</code>（<code>perf-ci</code>）逐 PR 验收；负载/饱和/轨迹长测报告只由 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/.github/workflows/perf-nightly.yml" target="_blank" rel="noreferrer">perf-nightly</a>（夜跑、手动、发布触发）产出，artifact 保留 30 天，从不充当 PR 门禁。</li><li><strong>备份恢复</strong>：<a href="./../tutorials/backup-restore">备份与独立环境恢复演练</a>在独立 Restore Environment 上验证文档、附件与任务；归档不含密钥，演练结束清理凭据与证书。</li><li><strong>删例</strong>：<a href="./../tutorials/example-removal">移除示例</a>按所有权清单执行，CI 的 example-removal job 每个 PR 完整演练一遍；删后 <code>just check-core</code> 全绿。</li><li><strong>生成引用</strong>：API 合同从 OpenAPI 生成（<code>contracts:check</code> 防漂移），配置参考从 Settings 生成并与 <code>.env.example</code> 交叉核对；权限与任务目录以教程叙述承载，暂无生成引用——如实记录，不虚报。</li></ul><h2 id="发布与复现" tabindex="-1">发布与复现 <a class="header-anchor" href="#发布与复现" aria-label="Permalink to &quot;发布与复现&quot;">​</a></h2><p>站点发布在 <a href="https://caizongyuan.github.io/axum-saas-template/" target="_blank" rel="noreferrer">https://caizongyuan.github.io/axum-saas-template/</a>，随 <code>main</code> 持续更新；每个页面页脚的“源码版本”就是该页验收时对应的仓库提交，发布任务会校验文档产物与提交一致后才上线，完整复现步骤见<a href="./../">快速开始</a>。v1 里程碑验证命令：<code>just check-full</code>。</p><hr><p>源码版本：<code>48dbe12f4905</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/48dbe12f490551b1545d0ba146a52dc218aa2992/docs/architecture/v1-coverage.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>',19)])])}const h=e(o,[["render",d]]);export{u as __pageData,h as default};
